export default function(app){const assistant=app.getMount('geoai-assistant'),functions=app.getMount('imagery-functions'),temporal=app.getMount('temporal-comparison');let ai=null,compare=null,menu=null,content=null,timer=null,disposed=false;let handlers=[];function detach(){for(const [node,fn] of handlers)node.removeEventListener('toggle',fn);handlers=[];if(content&&functions.isConnected&&content.isConnected)functions.append(content);menu?.remove();menu=null;content=null;ai=null;compare=null}function mount(){if(disposed)return false;const a=assistant.querySelector('details'),c=temporal.querySelector('details'),f=functions.firstElementChild;if(!a||!c||!f)return false;if(menu&&ai===a&&compare===c&&menu.isConnected)return true;detach();ai=a;compare=c;content=f;menu=document.createElement('details');menu.style.cssText='border:1px solid var(--calcite-color-border-2);border-radius:8px;padding:10px;color:var(--calcite-color-text-1);font-size:13px;min-width:0';const h=document.createElement('summary');h.textContent='Plantillas ráster';h.style.cssText='cursor:pointer;font-weight:600;font-size:15px';menu.append(h,content);functions.append(menu);ai.open=false;compare.open=false;menu.open=false;for(const node of [ai,menu,compare]){const fn=()=>{if(node.open)for(const other of [ai,menu,compare])if(other!==node)other.open=false};node.addEventListener('toggle',fn);handlers.push([node,fn])}return true}function ensure(){if(mount()){clearInterval(timer);timer=null;return true}return false}app.actions.register('exploration-menu-state',()=>({ready:ensure(),assistantOpen:!!ai?.open,templatesOpen:!!menu?.open,comparisonOpen:!!compare?.open,assistantText:ai?.textContent.slice(0,80)||'',templatesText:content?.textContent.slice(0,80)||'',comparisonText:compare?.textContent.slice(0,80)||''}));app.actions.register('exploration-menu-open',({panel})=>{if(!ensure())throw Error('Los contenidos aún se están cargando');const target={assistant:ai,templates:menu,comparison:compare}[panel];if(panel!=='closed'&&!target)throw Error('Panel desconocido');for(const n of [ai,menu,compare])n.open=n===target;return {assistantOpen:ai.open,templatesOpen:menu.open,comparisonOpen:compare.open}});timer=setInterval(ensure,150);ensure();app.onCleanup(()=>{disposed=true;clearInterval(timer);detach()});}